 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Consecutive marker points define line segments. Fill their gaps with 2,
    # while preserving the marker colors at their endpoints.
    for r in range(h):
        pts = [c for c in range(w) if grid[r][c] != background]
        for a, b in zip(pts, pts[1:]):
            for c in range(a + 1, b): out[r][c] = 2
    for c in range(w):
        pts = [r for r in range(h) if grid[r][c] != background]
        for a, b in zip(pts, pts[1:]):
            for r in range(a + 1, b): out[r][c] = 2

    # Adjacent marker cells themselves change to 2 only when the line has
    # several consecutive adjacent-marker pairs (a dotted-pattern run).
    for r in range(h):
        pairs = [(a, b) for a, b in zip(range(w), range(1, w))
                 if grid[r][a] != background and grid[r][b] != background]
        if len(pairs) >= 2:
            for a, b in pairs: out[r][a] = out[r][b] = 2
    for c in range(w):
        pairs = [(a, b) for a, b in zip(range(h), range(1, h))
                 if grid[a][c] != background and grid[b][c] != background]
        if len(pairs) >= 2:
            for a, b in pairs: out[a][c] = out[b][c] = 2
    return out
