    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    # Detect maximal runs of cells not equal to background. In each row and
    # column, color background gaps between neighboring foreground runs.
    for r in range(h):
        runs = []
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
            else:
                a = c
                while c < w and grid[r][c] != bg:
                    c += 1
                runs.append((a, c - 1))
        for (_, a1), (b0, _) in zip(runs, runs[1:]):
            for c in range(a1 + 1, b0):
                out[r][c] = 2
    for c in range(w):
        runs = []
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
            else:
                a = r
                while r < h and grid[r][c] != bg:
                    r += 1
                runs.append((a, r - 1))
        for (_, a1), (b0, _) in zip(runs, runs[1:]):
            for r in range(a1 + 1, b0):
                out[r][c] = 2
    return out
