 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    # Fill short gaps between successive runs of the minority color.
    # Gaps of more than three cells are not connected.
    def runs(vals):
        result = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            start = i
            while i < len(vals) and vals[i] != bg:
                i += 1
            result.append((start, i - 1))
        return result
    for r in range(h):
        rr = runs(grid[r])
        for (_, end), (start, _) in zip(rr, rr[1:]):
            if 0 < start - end - 1 <= 3:
                for c in range(end + 1, start):
                    out[r][c] = 2
    for c in range(w):
        cc = runs([grid[r][c] for r in range(h)])
        for (_, end), (start, _) in zip(cc, cc[1:]):
            if 0 < start - end - 1 <= 3:
                for r in range(end + 1, start):
                    out[r][c] = 2
    return out
