    h, w = len(grid), len(grid[0])
    # Foreground is the least frequent color; 2 marks missing cells along
    # interrupted horizontal/vertical foreground lines.
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    # Infer the characteristic spacing from the repeated line motifs: connect
    # only if the intervening run length matches the dominant small gap (1-2).
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != bg]
        for a, b in zip(cols, cols[1:]):
            gap = b - a - 1
            if 1 <= gap <= 2:
                for c in range(a + 1, b): out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(rows, rows[1:]):
            gap = b - a - 1
            if 1 <= gap <= 2:
                for r in range(a + 1, b): out[r][c] = 2
    return out
